// Actual portable public dual-slot/trace state; no COM, GPIO or credentials.
#include "../05-test/hx_failure_diag.h"
#include <cassert>
#include <cstdio>
#include <cstring>
struct Capture {
  HxDiagState any, link; uint32_t seq = 0, rx = 0, err = 0;
  Capture(uint32_t start = 0) { link.trigger_mask = HXD_LINK; hxdiagBegin(any, start); hxdiagBegin(link, start); }
  void feed(int32_t raw = -162000, bool accepted = true, uint32_t at = 0xFFFFFFFFU) { HxDiagRecord r = {}; r.seq = ++seq; r.start_us = at == 0xFFFFFFFFU ? seq * 10000 : at; r.end_us = r.start_us + 200; r.bits24 = static_cast<uint32_t>(raw) & 0xFFFFFF; r.raw = raw; r.rx_before = rx; r.err_before = err; if (accepted) ++rx; else ++err; r.rx_after = rx; r.err_after = err; r.accepted = accepted; r.dout_after25 = accepted; r.pulses_issued = 25; r.context_flags = seq > 1 ? 1 : 0; hxdiagObserveShared(any, r); hxdiagObserveShared(link, r); hxdiagSeal(any); hxdiagSeal(link); }
  void tick(uint32_t now) { hxdiagTick(any, now); hxdiagTick(link, now); hxdiagSeal(any); hxdiagSeal(link); }
};
static const HxDiagRecord &at(const HxDiagState &s, uint16_t i) { return s.records[hxdiagIndex(s, i)]; }
static const HxDiagRecord *find(const HxDiagState &s, uint32_t seq) { for (uint16_t i = 0; i < s.count; ++i) if (at(s, i).seq == seq) return &at(s, i); return nullptr; }
int main() {
  unsigned passed = 0;
  { Capture c; for (unsigned i = 0; i < 200; ++i) c.feed(); c.feed(-80); for (unsigned i = 0; i < 128; ++i) c.feed(); assert(c.any.mode == HXD_FROZEN && c.any.trigger_seq == 201 && c.link.mode == HXD_LIVE); const auto copy = c.any; for (unsigned i = 0; i < 100; ++i) c.feed(); c.feed(-317, false); const uint32_t link_seq = c.seq; for (unsigned i = 0; i < 128; ++i) c.feed(); assert(c.link.mode == HXD_FROZEN && c.link.trigger_seq == link_seq && c.link.trigger_flags == HXD_LINK && c.any.trigger_seq == 201); assert(std::memcmp(copy.records, c.any.records, sizeof(copy.records)) == 0); assert(copy.export_attempts == c.any.export_attempts && copy.export_pre_overwritten == c.any.export_pre_overwritten && copy.export_omitted == c.any.export_omitted); ++passed; }
  { Capture c; c.feed(); c.feed(-317, false); assert(c.any.trigger_seq == 2 && c.link.trigger_seq == 2 && c.any.trigger_flags == 1 && c.link.trigger_flags == 1); for (unsigned i = 0; i < 128; ++i) c.feed(); assert(c.any.export_sealed && c.link.export_sealed); for (uint16_t i = 0; i < c.any.count; ++i) assert(hxdiagCrc(at(c.any, i)) == hxdiagCrc(at(c.link, i))); ++passed; }
  { Capture c; c.feed(); c.feed(-80); c.feed(); c.feed(-317, false); assert(c.any.mode == HXD_POST_CAPTURE && c.any.trigger_seq == 2 && c.link.trigger_seq == 4 && hxdiagCanRetain(c.link, 50000)); HxFailureDiag f; assert(hxfStart(f, 4, 40000, 40200, 0xFFFEC3, 3, 1, 0, 0, true, 40201)); assert(f.mode == HXF_HOLD && c.any.trigger_seq != f.seq && c.link.trigger_seq == f.seq); ++passed; }
  { Capture c; for (unsigned i = 0; i < 400; ++i) c.feed(i == 300 ? -80 : -162000); assert(c.link.mode == HXD_LIVE && c.link.count == 127 && !c.link.trigger_flags); bool jump_seen = false; for (uint16_t i = 0; i < c.link.count; ++i) jump_seen |= (at(c.link, i).flags & HXD_JUMP) != 0; assert(jump_seen); ++passed; }
  { Capture c; for (unsigned i = 0; i < 300; ++i) c.feed(); c.tick(HXD_WINDOW_US); assert(c.any.freeze_reason == HXD_WINDOW_LIMIT && c.link.freeze_reason == HXD_WINDOW_LIMIT && c.any.start_us == c.link.start_us && c.any.export_sealed && c.link.export_sealed); assert(c.any.count == 127 && c.link.count == 127 && !c.link.trigger_flags); ++passed; }
  { Capture c; c.feed(); c.feed(-80); for (unsigned i = 0; i < 128; ++i) c.feed(); assert(c.any.mode == HXD_FROZEN && hxdiagCanRetain(c.link, 1400000) && !hxdiagCanRetain(c.any, 1400000)); c.feed(-317, false); assert(c.link.trigger_seq == c.seq && c.link.trigger_flags == HXD_LINK); ++passed; }
  { Capture c; c.feed(-317, false, 1000); const uint32_t boundary = c.link.trigger_us + HXD_POST_US; assert(hxdiagCanRetain(c.link, boundary - 1) && !hxdiagCanRetain(c.link, boundary)); c.feed(-317, false, boundary); assert(c.link.freeze_reason == HXD_POST_TIMEOUT && c.link.count == 1 && c.link.export_omitted == 1); ++passed; }
  { Capture c; c.feed(-317, false, HXD_WINDOW_US - 100); assert(c.link.count == 1 && at(c.link, 0).end_us > HXD_WINDOW_US && c.link.freeze_reason == HXD_WINDOW_LIMIT); assert(!hxdiagCanRetain(c.link, HXD_WINDOW_US)); HxFailureDiag f; hxfStop(f, HXF_STOP_WINDOW, HXD_WINDOW_US + 100); assert(!f.captured && f.mode == HXF_CLOSED_NO_LINK); ++passed; }
  { Capture c; c.feed(-317, false); c.tick(c.link.trigger_us + HXD_POST_US); const uint32_t attempts = c.link.export_attempts, omitted = c.link.export_omitted; for (unsigned i = 0; i < 10; ++i) c.feed(); hxdiagSeal(c.link); assert(c.link.export_attempts == attempts && c.link.export_omitted == omitted && c.link.attempts > attempts && c.link.omitted_after_freeze > omitted); assert(c.link.export_attempts == c.link.export_pre_overwritten + c.link.count + c.link.export_omitted); ++passed; }
  { Capture c; for (unsigned i = 0; i < 200; ++i) c.feed(); c.feed(-80); c.feed(); c.feed(-317, false); for (unsigned i = 0; i < 128; ++i) c.feed(); unsigned overlap = 0; for (uint16_t i = 0; i < c.link.count; ++i) { const auto &r = at(c.link, i); const auto *a = find(c.any, r.seq); if (a) { assert(hxdiagCrc(*a) == hxdiagCrc(r) && std::memcmp(a, &r, sizeof(r)) == 0); ++overlap; } } assert(overlap > 200); ++passed; }
  { Capture c(0xFFF00000U); c.seq = 0xFFFFFFFFU; c.feed(-162000, true, 0xFFF00100U); assert(c.any.seq_wrapped && c.link.seq_wrapped && at(c.any, 0).seq == 0 && at(c.link, 0).seq == 0); c.tick(static_cast<uint32_t>(0xFFF00000U + HXD_WINDOW_US)); assert(c.any.export_sealed && c.link.export_sealed); ++passed; }
  { Capture c; c.feed(); c.feed(-80); for (unsigned i = 0; i < 128; ++i) c.feed(); HxFailureDiag f; hxfStart(f, 131, 1310000, 1310200, 0xFFFEC3, c.rx, 1, 0, 0, true, 1310201); c.feed(-317, false); hxfStop(f, HXF_STOP_RING, 1310300); assert(c.any.mode == HXD_FROZEN && hxdiagCanRetain(c.link, 1320000)); hxfResume(f, 1320000, 132, hxdiagCanRetain(c.link, 1320000)); assert(f.resume_valid); const uint32_t crc = hxfCrc(f); c.tick(HXD_WINDOW_US); hxfResume(f, HXD_WINDOW_US + 1, 132, hxdiagCanRetain(c.link, HXD_WINDOW_US + 1)); assert(hxfCrc(f) == crc); ++passed; }
  { Capture c; c.feed(-317, false); HxFailureDiag f; hxfStart(f, 1, 10000, 10200, 0xFFFEC3, 0, 1, 3, 1, false, 10201); assert(f.mode == HXF_SKIPPED_BUSY && c.link.trigger_seq == 1); const uint32_t crc = hxfCrc(f); c.feed(-317, false); assert(!hxfStart(f, 2, 20000, 20200, 0xFFFEC3, 0, 2, 0, 0, true, 20201) && hxfCrc(f) == crc); ++passed; }
  { static_assert(sizeof(HxDiagRecord) == 56, "row ABI changed"); static_assert(2 * sizeof(HxDiagState) + sizeof(HxFailureDiag) <= 30000, "diagnostic RAM budget exceeded"); Capture c; assert(c.any.records != c.link.records && sizeof(c.any.records) + sizeof(c.link.records) == 28672); ++passed; }
  std::printf("%u native dual-slot cases passed; slot_state=%zu, two_states_plus_trace=%zu, ring_payload=%zu bytes. Not physical timing validation.\n", passed, sizeof(HxDiagState), 2 * sizeof(HxDiagState) + sizeof(HxFailureDiag), 2 * sizeof(HxDiagState::records));
}
